module LineIntersectionCounter(\n    input clk,\n    input rst_n,\n    input start,\n    input signed [31:0] x0_0, y0_0, x1_0, y1_0,\n    input signed [31:0] x0_1, y0_1, x1_1, y1_1,\n    input signed [31:0] x0_2, y0_2, x1_2, y1_2,\n    input [2:0] line_valid,\n    output reg done,\n    output reg signed [7:0] count\n);\n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] COMPUTE      = 3'd1;\n    localparam [2:0] DEDUPLICATE  = 3'd2;\n    localparam [2:0] FINISH       = 3'd3;\n    \n    reg [2:0] state, next_state;\n    reg signed [63:0] dx_i, dy_i, dx_j, dy_j;\n    reg signed [63:0] D;          // Denominator\n    reg signed [63:0] t1_num, t2_num;\n    reg signed [63:0] collinear_check;\n    reg [1:0] pair_index;         // 0:(0,1), 1:(0,2), 2:(1,2)\n    reg [7:0] cycle_count;\n    reg infinite_detected;\n    \n    // Intersection storage (max 3 pairs, 3 points)\n    reg signed [63:0] x_num [0:2];\n    reg signed [63:0] y_num [0:2];\n    reg signed [63:0] denom [0:2];\n    reg [1:0] num_points;\n    reg [1:0] valid_point [0:2];  // 1 if valid point\n    \n    // Dedup counters\n    reg [1:0] dedup_i, dedup_j;\n    reg [2:0] unique_count;\n    reg [2:0] unique_flags;\n    \n    // Pair validity\n    wire pair_valid [0:2];\n    assign pair_valid[0] = line_valid[0] && line_valid[1];\n    assign pair_valid[1] = line_valid[0] && line_valid[2];\n    assign pair_valid[2] = line_valid[1] && line_valid[2];\n    \n    // State and cycle control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            count <= 8'd0;\n            cycle_count <= 8'd0;\n            infinite_detected <= 1'b0;\n            pair_index <= 2'd0;\n            for (integer i = 0; i < 3; i = i + 1) begin\n                x_num[i] <= 64'd0;\n                y_num[i] <= 64'd0;\n                denom[i] <= 64'd0;\n                valid_point[i] <= 1'b0;\n            end\n            num_points <= 2'd0;\n            dedup_i <= 2'd0;\n            dedup_j <= 2'd0;\n            unique_count <= 3'd0;\n            unique_flags <= 3'b111;\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    pair_index <= 2'd0;\n                    infinite_detected <= 1'b0;\n                    for (integer i = 0; i < 3; i = i + 1) begin\n                        valid_point[i] <= 1'b0;\n                    end\n                    num_points <= 2'd0;\n                    unique_flags <= 3'b111;\n                    if (start) state <= COMPUTE;\n                end\n                \n                COMPUTE: begin\n                    // Process current pair_index\n                    if (pair_valid[pair_index]) begin\n                        // Get line indices i and j\n                        case (pair_index)\n                            2'd0: begin // Pair (0,1)\n                                dx_i <= (x1_0 - x0_0);\n                                dy_i <= (y1_0 - y0_0);\n                                dx_j <= (x1_1 - x0_1);\n                                dy_j <= (y1_1 - y0_1);\n                            end\n                            2'd1: begin // Pair (0,2)\n                                dx_i <= (x1_0 - x0_0);\n                                dy_i <= (y1_0 - y0_0);\n                                dx_j <= (x1_2 - x0_2);\n                                dy_j <= (y1_2 - y0_2);\n                            end\n                            2'd2: begin // Pair (1,2)\n                                dx_i <= (x1_1 - x0_1);\n                                dy_i <= (y1_1 - y0_1);\n                                dx_j <= (x1_2 - x0_2);\n                                dy_j <= (y1_2 - y0_2);\n                            end\n                        endcase\n                        \n                        // Compute denominator D\n                        D <= dx_i * dy_j - dx_j * dy_i;\n                        \n                        // Check D == 0\n                        if (D == 64'd0) begin\n                            // Compute collinear check: (x0_j - x0_i)*dy_i - (y0_j - y0_i)*dx_i\n                            case (pair_index)\n                                2'd0: collinear_check <= (x0_1 - x0_0) * dy_i - (y0_1 - y0_0) * dx_i;\n                                2'd1: collinear_check <= (x0_2 - x0_0) * dy_i - (y0_2 - y0_0) * dx_i;\n                                2'd2: collinear_check <= (x0_2 - x0_1) * dy_i - (y0_2 - y0_1) * dx_i;\n                            endcase\n                            \n                            // Check collinear (collinear_check == 0)\n                            if (collinear_check == 64'd0) begin\n                                // Check overlap - compute projections\n                                reg signed [63:0] v_dot_i, n2, n3;\n                                reg signed [63:0] overlap_min, overlap_max;\n                                v_dot_i = dx_i * dx_i + dy_i * dy_i;  // v_dot_i is squared length\n                                \n                                case (pair_index)\n                                    2'd0: begin// Get line j start and end relative to line i\n                                        n2 = (x0_1 - x0_0) * dx_i + (y0_1 - y0_0) * dy_i;\n                                        n3 = (x1_1 - x0_0) * dx_i + (y1_1 - y0_0) * dy_i;\n                                    end\n                                    2'd1: begin\n                                        n2 = (x0_2 - x0_0) * dx_i + (y0_2 - y0_0) * dy_i;\n                                        n3 = (x1_2 - x0_0) * dx_i + (y1_2 - y0_0) * dy_i;\n                                    end\n                                    2'd2: begin\n                                        n2 = (x0_2 - x0_1) * dx_i + (y0_2 - y0_1) * dy_i;\n                                        n3 = (x1_2 - x0_1) * dx_i + (y1_2 - y0_1) * dy_i;\n                                    end\n                                endcase\n                                \n                                overlap_min = (n2 < n3) ? n2 : n3;\n                                overlap_max = (n2 < n3) ? n3 : n2;\n                                \n                                if ((overlap_max >= 0 && overlap_max < v_dot_i) || (overlap_min > 0 && overlap_min <= v_dot_i))\n                                    infinite_detected <= 1'b1;\n                            end\n                        end else begin\n                            // D != 0 - compute intersection\n                            case (pair_index) \n                                2'd0: begin// Compute t1 numerator (j relative to i)\n                                    t1_num <= (x0_1 - x0_0) * dy_j - (y0_1 - y0_0) * dx_j;\n                                    t2_num <= (x0_1 - x0_0) * dy_i - (y0_1 - y0_0) * dx_i;\n                                end\n                                2'd1: begin\n                                    t1_num <= (x0_2 - x0_0) * dy_j - (y0_2 - y0_0) * dx_j;\n                                    t2_num <= (x0_2 - x0_0) * dy_i - (y0_2 - y0_0) * dx_i;\n                                end\n                                2'd2: begin\n                                    t1_num <= (x0_2 - x0_1) * dy_j - (y0_2 - y0_1) * dx_j;\n                                    t2_num <= (x0_2 - x0_1) * dy_i - (y0_2 - y0_1) * dx_i;\n                                end\n                            endcase\n                            \n                            // Check if 0 <= t1 <= D and 0 <= t2 <= D\n                            if (((t1_num >= 0 && t1_num <= D) || (t1_num <= 0 && t1_num >= D)) &&\n                                ((t2_num >= 0 && t2_num <= D) || (t2_num <= 0 && t2_num >= D))) begin\n                                // Valid intersection - store point\n                                case (pair_index)\n                                    2'd0: begin\n                                        x_num[num_points] <= x0_0 * D + t1_num * dx_i;\n                                        y_num[num_points] <= y0_0 * D + t1_num * dy_i;\n                                        denom[num_points] <= D;\n                                    end\n                                    2'd1: begin\n                                        x_num[num_points] <= x0_0 * D + t1_num * dx_i;\n                                        y_num[num_points] <= y0_0 * D + t1_num * dy_i;\n                                        denom[num_points] <= D;\n                                    end\n                                    2'd2: begin\n                                        x_num[num_points] <= x0_1 * D + t1_num * dx_i;\n                                        y_num[num_points] <= y0_1 * D + t1_num * dy_i;\n                                        denom[num_points] <= D;\n                                    end\n                                endcase\n                                valid_point[num_points] <= 1'b1;\n                                num_points <= num_points + 2'd1;\n                            end\n                        end\n                    end\n                    \n                    // Move to next pair or next state\n                    if (pair_index == 2'd2) begin\n                        state <= DEDUPLICATE;\n                    end else begin\n                        pair_index <= pair_index + 2'd1;\n                    end\n                    \n                    // Check cycle limit\n                    if (cycle_count >= 8'd90) begin\n                        state <= FINISH;\n                        infinite_detected <= 1'b1;\n                    end\n                end\n                \n                DEDUPLICATE: begin\n                    // Reset dedup counters\n                    if (dedup_i == 2'd0 && dedup_j == 2'd0) begin\n                        unique_count <= 3'd0;\n                        unique_flags <= 3'b111;\n                    end\n                    \n                    // Nested loops to compare points i and j\n                    if (valid_point[dedup_i] && valid_point[dedup_j] && dedup_i != dedup_j) begin\n                        // Check equality: x_i * D_j == x_j * D_i and y_i * D_j == y_j * D_i\n                        if (x_num[dedup_i] * denom[dedup_j] === x_num[dedup_j] * denom[dedup_i] &&\n                            y_num[dedup_i] * denom[dedup_j] === y_num[dedup_j] * denom[dedup_i]) begin\n                            unique_flags[dedup_j] <= 1'b0;  // Mark j as duplicate\n                        end\n                    end\n                    \n                    // Increment dedup counters\n                    if (dedup_j < num_points) begin\n                        dedup_j <= dedup_j + 2'd1;\n                    end else if (dedup_i < num_points) begin\n                        dedup_i <= dedup_i + 2'd1;\n                        dedup_j <= 2'd0;\n                    end else begin\n                        // Dedup complete - count unique points\n                        unique_count <= unique_flags[0] + unique_flags[1] + unique_flags[2];\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    count <= (infinite_detected) ? 8'd255 : unique_count[7:0];\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule